import re

# Load all grids from the session
d = os.environ.get('RLM_SESSION_DIR')
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()

G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

def print_grid(g, title=""):
    print(f"\n=== {title} ===")
    print(f"Dimensions: {len(g)}x{len(g[0])}")
    for i, row in enumerate(g):
        line = ' '.join(f'{x:2}' for x in row)
        print(f"Row {i:2d}: {line}")

    # Find special colors (not background, not separator)
    bg = g[0][0]  # Usually background
    sep_colors = set()
    for i in range(min(len(g), 5)):
        for j in range(min(len(g[0]), 5)):
            if i > 0 and g[i][j] == g[i-1][j]:
                sep_colors.add(g[i][j])

    print(f"\nBackground: {bg}")
    print(f"Possible separator colors: {sep_colors}")

    # Find all non-background cells
    non_bg_coords = []
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] != bg:
                non_bg_coords.append((i, j, g[i][j]))
    print(f"\nNon-background cells: {non_bg_coords}")

